// most of the time we compute square root
    float root(float x) {
        return pow(x,1/2.0);
    }

// ... but we can do any root
    float root(float x, float y) {
        return pow(x,1/y);
    }

int main( void )
{
    float x1 = 4, x2 = 27;

    printf("Square root of %.1f = %.3f\n", x1, root(x1));
    printf("Cubic root of %.1f = %.3f\n", x2, root(x2,3));

    return 0;
}

